import{_ as e,o as r,c as a,ag as d}from"./chunks/framework.4s5LDCII.js";const p=JSON.parse('{"title":"儿童青少年肥胖食养指南（2024年版）","description":"国家卫健委《儿童青少年肥胖食养指南（2024年版）》可执行整理：家长能直接照做的行动清单，每条出处可一键跳回原文对应页。","frontmatter":{"title":"儿童青少年肥胖食养指南（2024年版）","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2024年版","published":"2024-02","source_url":"https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128961_34845.pdf","status":"现行","tags":["儿童肥胖","青少年","食养","饮食指导","行动清单"],"reviewed":false,"description":"国家卫健委《儿童青少年肥胖食养指南（2024年版）》可执行整理：家长能直接照做的行动清单，每条出处可一键跳回原文对应页。"},"headers":[],"relativePath":"guides/child-obesity-2024.md","filePath":"guides/child-obesity-2024.md"}'),i={name:"guides/child-obesity-2024.md"};function h(s,t,o,g,l,n){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="儿童青少年肥胖食养指南-2024年版" tabindex="-1">儿童青少年肥胖食养指南（2024年版） <a class="header-anchor" href="#儿童青少年肥胖食养指南-2024年版" aria-label="Permalink to &quot;儿童青少年肥胖食养指南（2024年版）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据官方 PDF 原文整理，尚未逐条对照原文校验；校验通过前请以原文为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页所有建议均<strong>整理自官方文件原文</strong>，每条&quot;出处&quot;均可点击直达原文对应页；标注【本站提示】的少数条目为中性工具提示，不代表医学建议。本站不构成诊疗建议，与医生的治疗方案冲突时，<strong>以医嘱为准</strong>。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128961_34845.pdf" target="_blank" rel="noreferrer">官方全文 PDF（卫健委直链）</a>）· 一级来源。下文&quot;出处&quot;链接指向本站镜像的<a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf" target="_blank" rel="noreferrer">官方原文 PDF</a>（政府公文，属公共领域）。</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>超重、肥胖的儿童青少年及其家长，也面向校医、营养指导人员（<a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=3" target="_blank" rel="noreferrer">原文·前言</a>）。<strong>儿童减重以&quot;保证生长发育&quot;为前提，方案请经专业评估后执行。</strong></p><h2 id="速览卡-一屏看完" tabindex="-1">速览卡（一屏看完） <a class="header-anchor" href="#速览卡-一屏看完" aria-label="Permalink to &quot;速览卡（一屏看完）&quot;">​</a></h2><p><strong>六条原则</strong>：小份多样、保持合理膳食结构 → 辨证施食、因人因时因地制宜 → 良好饮食行为 → 积极身体活动 → 多方合作创造支持环境 → 定期监测科学管理体重。（<a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=6" target="_blank" rel="noreferrer">原文·三</a>）</p><table tabindex="0"><thead><tr><th>关键数字</th><th>数值</th><th>出处</th></tr></thead><tbody><tr><td>食物品种</td><td>每天 <strong>≥12 种</strong>、每周 <strong>≥25 种</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>奶类</td><td>学龄前（2～5 岁）<strong>350～500mL/日</strong>；学龄（6～17 岁）<strong>300mL 以上/日</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>三餐能量比</td><td>早 <strong>25%～30%</strong>、午 <strong>35%～40%</strong>、晚 <strong>30%～35%</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>用餐时长</td><td>早餐约 20 分钟、午晚餐约 30 分钟；<strong>晚 9 点后尽量不进食</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>零食供能</td><td>不超过每日总能量 <strong>10%</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>身体活动</td><td>学龄前每天 <strong>3 小时</strong>（含户外 2 小时）；学龄儿童每天 <strong>≥60 分钟</strong>中高强度</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>肥胖儿童运动</td><td>从每天 20 分钟起步渐增至 <strong>20～60 分钟</strong>；每周 <strong>3～4 次</strong>、每次 20～60 分钟</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>睡眠</td><td>5 岁以下 <strong>10～13h</strong>；6～12 岁 <strong>9～12h</strong>；13～17 岁 <strong>8～10h</strong></td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>视屏</td><td>学龄前 ≤1h/日；学龄 ≤2h/日；久坐 ≤1h/次</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr></tbody></table><h2 id="行动清单" tabindex="-1">行动清单 <a class="header-anchor" href="#行动清单" aria-label="Permalink to &quot;行动清单&quot;">​</a></h2><h3 id="🛒-买-🍚-吃" tabindex="-1">🛒 买 / 🍚 吃 <a class="header-anchor" href="#🛒-买-🍚-吃" aria-label="Permalink to &quot;🛒 买 / 🍚 吃&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>小份多样：每天 12 种以上食物，谷薯、蔬果、禽畜鱼蛋奶、大豆坚果都覆盖</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>增加新鲜蔬果、全谷物和杂豆比重；保证优质蛋白（鱼、禽、蛋、瘦肉、奶、大豆）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>零食首选奶类、新鲜蔬果、原味坚果；结合营养标签，少吃高油高盐高糖的过度加工食品</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td><strong>不喝含糖饮料</strong>，足量白水少量多次</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>尽量在家就餐；在外就餐也保证蔬菜、全谷物，控油炸甜食饮料</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>肥胖儿童进餐顺序：先吃蔬菜 → 鱼禽肉蛋豆类 → 最后谷薯类</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>按证型辨证施食，因人因时因地制宜</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(二)</a></td></tr></tbody></table><h3 id="🏃-动-😴-睡" tabindex="-1">🏃 动 / 😴 睡 <a class="header-anchor" href="#🏃-动-😴-睡" aria-label="Permalink to &quot;🏃 动 / 😴 睡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>学龄儿童每天 ≥60 分钟以有氧为主的中高强度运动（快走、骑车、游泳、球类）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>每周至少 3 天高强度/抗阻运动（跳绳、跳远、攀爬、弹力带）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>肥胖儿童在运动处方师等指导下循序渐进制订方案</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>家长与孩子共同运动，营造家庭运动氛围</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>保证睡眠时长（见速览卡），早睡早起；久坐每次 ≤1 小时</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr><tr><td>关注情绪性进食等心理行为问题，必要时心理干预</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr></tbody></table><h3 id="🩺-测与就医" tabindex="-1">🩺 测与就医 <a class="header-anchor" href="#🩺-测与就医" aria-label="Permalink to &quot;🩺 测与就医&quot;">​</a></h3><table tabindex="0"><thead><tr><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>定期监测身高体重，科学指导体重管理</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=11" target="_blank" rel="noreferrer">三(六)</a></td></tr><tr><td>肥胖判定按年龄段标准（见附录5）</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=38" target="_blank" rel="noreferrer">附录5</a></td></tr><tr><td>学校、家庭、医疗机构多方合作，创造支持环境</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=11" target="_blank" rel="noreferrer">三(五)</a></td></tr></tbody></table><h2 id="常见误区-原文明确告诫" tabindex="-1">常见误区（原文明确告诫） <a class="header-anchor" href="#常见误区-原文明确告诫" aria-label="Permalink to &quot;常见误区（原文明确告诫）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>原文怎么说</th><th>出处</th></tr></thead><tbody><tr><td>&quot;孩子减肥靠饿&quot;</td><td>应保证平衡膳食、营养素摄入适宜，以生长发育为前提</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=6" target="_blank" rel="noreferrer">三(一)</a></td></tr><tr><td>&quot;零食一口不能吃&quot;</td><td>零食可选奶类、蔬果、原味坚果，供能 ≤10% 即可</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>&quot;吃快点没事&quot;</td><td>细嚼慢咽、用餐时长适宜，进餐结束立即离开餐桌</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=8" target="_blank" rel="noreferrer">三(三)</a></td></tr><tr><td>&quot;运动越猛越好&quot;</td><td>循序渐进，从每天 20 分钟起步，在专业评估指导下制订方案</td><td><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=9" target="_blank" rel="noreferrer">三(四)</a></td></tr></tbody></table><h2 id="附录怎么用" tabindex="-1">附录怎么用 <a class="header-anchor" href="#附录怎么用" aria-label="Permalink to &quot;附录怎么用&quot;">​</a></h2><ul><li><strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=13" target="_blank" rel="noreferrer">附录1《肥胖儿童青少年的食物选择》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=16" target="_blank" rel="noreferrer">附录2《常见食物交换表》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=21" target="_blank" rel="noreferrer">附录3《不同地区食谱示例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=34" target="_blank" rel="noreferrer">附录4《食养方举例》</a></strong> · <strong><a href="https://yshuai.github.io/SageRelay/guides-pdf/child-obesity-2024.pdf#page=38" target="_blank" rel="noreferrer">附录5《不同年龄段肥胖判定》</a></strong>。</li></ul><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2024 年版（现行）</td></tr><tr><td>印发时间</td><td>2024 年 2 月</td></tr><tr><td>原文直链</td><td><a href="https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369/files/1732845128961_34845.pdf" target="_blank" rel="noreferrer">卫健委官网 PDF</a></td></tr></tbody></table>',22)])])}const b=e(i,[["render",h]]);export{p as __pageData,b as default};
